insert into public.translations (locale, key, value) values
  ('pt-BR', 'site.doctor.integration.error.inUse', $json$"Esta Integração tem histórico (Execuções, Eventos, Conectores ou Importações) e não pode ser excluída. Arquive-a."$json$::jsonb),
  ('pt-BR', 'site.doctor.integrations.edit', $json$"Editar"$json$::jsonb),
