  ('pt-BR', 'site.doctor.integrations.deleteBody', $json$"{name} e os mapas de identificadores dela são excluídos de vez. Só dá para excluir uma Integração sem histórico; com Execuções, Eventos, Conectores ou Importações, arquive-a."$json$::jsonb),
