  ('es', 'site.doctor.integrations.deleteBody', $json$"{name} y sus mapas de identificadores se eliminan definitivamente. Solo se puede eliminar una Integración sin historial; con Ejecuciones, Eventos, Conectores o Importaciones, archívala."$json$::jsonb),
  ('fr', 'site.doctor.integration.error.inUse', $json$"Cette Intégration a un historique (Exécutions, Événements, Connecteurs ou Imports) et ne peut pas être supprimée. Archivez-la."$json$::jsonb),
