  ('fr', 'site.doctor.integrations.deleteBody', $json$"{name} et ses correspondances d'identifiants sont supprimés définitivement. Seule une Intégration sans historique peut être supprimée ; avec des Exécutions, Événements, Connecteurs ou Imports, archivez-la."$json$::jsonb),
  ('de', 'site.doctor.integration.error.inUse', $json$"Diese Integration hat einen Verlauf (Ausführungen, Ereignisse, Konnektoren oder Importe) und kann nicht gelöscht werden. Archiviere sie stattdessen."$json$::jsonb),
  ('de', 'site.doctor.integrations.edit', $json$"Bearbeiten"$json$::jsonb),
