  ('de', 'site.doctor.integrations.deleteTitle', $json$"{name} löschen"$json$::jsonb),
  ('de', 'site.doctor.integrations.deleteBody', $json$"{name} und ihre Kennungszuordnungen werden endgültig gelöscht. Nur eine Integration ohne Verlauf kann gelöscht werden; mit Ausführungen, Ereignissen, Konnektoren oder Importen archiviere sie stattdessen."$json$::jsonb),
  ('ja', 'site.doctor.integration.error.inUse', $json$"この連携には履歴（実行、イベント、コネクタ、インポート）があるため削除できません。アーカイブしてください。"$json$::jsonb),
  ('ja', 'site.doctor.integrations.edit', $json$"編集"$json$::jsonb),
