  ('hi', 'site.doctor.integrations.deleteTitle', $json$"{name} हटाएं"$json$::jsonb),
  ('hi', 'site.doctor.integrations.deleteBody', $json$"{name} और उसके पहचानकर्ता मैप हमेशा के लिए हटा दिए जाते हैं। केवल बिना इतिहास वाले इंटीग्रेशन को हटाया जा सकता है; निष्पादन, इवेंट, कनेक्टर या इंपोर्ट होने पर इसे संग्रहित करें।"$json$::jsonb)
